const input = $input.first().json;
const body = input.body;
const headers = input.headers ?? {};
const idempotencyKey = headers['idempotency-key'];

let error = null;
let message = '';

if (!body || typeof body !== 'object' || Array.isArray(body)) {
  error = 'INVALID_BODY';
  message = 'El cuerpo de la solicitud debe ser un objeto JSON';
} else if (typeof body.message !== 'string') {
  error = 'INVALID_MESSAGE';
  message = 'El campo "message" es obligatorio y debe ser texto';
} else if (body.message.trim().length === 0) {
  error = 'EMPTY_MESSAGE';
  message = 'El campo "message" no puede estar vacÃ­o';
} else if (body.message.trim().length > 2000) {
  error = 'MESSAGE_TOO_LONG';
  message = 'El campo "message" no puede superar los 2000 caracteres';
} else if (
  typeof idempotencyKey !== 'string' ||
  !/^[a-zA-Z0-9_-]{8,255}$/.test(idempotencyKey)
) {
  error = 'INVALID_IDEMPOTENCY_KEY';
  message = 'El encabezado Idempotency-Key es obligatorio y debe tener entre 8 y 255 caracteres alfanumÃ©ricos, guiones o guiones bajos';}

if (error) {
  return [
    {
      json: {
        valid: false,
        error,
        message,
      },
    },
  ];
}

return [
  {
    json: {
      ...input,
      valid: true,
      idempotencyKey,
      body: {
        ...body,
        message: body.message.trim(),
      },
    },
  },
];

const result = $input.first().json;

// Recuperar el mensaje original del Webhook
const original = $('Webhook').first().json.body ?? {};
const description = original.message ?? original.description ?? '';

if (typeof description !== 'string' || !description.trim()) {
  throw new Error('No se encontrÃ³ el mensaje original del ticket');
}

// Parsear la respuesta de Ollama
let ticket;

try {
  ticket = JSON.parse(result.response);
} catch {
  throw new Error('Ollama devolviÃ³ una respuesta que no es JSON vÃ¡lido');
}

if (!ticket || typeof ticket !== 'object' || Array.isArray(ticket)) {
  throw new Error('La respuesta de Ollama debe ser un objeto JSON');
}

// Normalizar categorÃ­a y prioridad
const category =
  typeof ticket.category === 'string'
    ? ticket.category.trim().toLowerCase()
    : '';

const priority =
  typeof ticket.priority === 'string'
    ? ticket.priority.trim().toLowerCase()
    : '';

const validCategories = [
  'hardware',
  'software',
  'network',
  'access',
  'security',
  'other',
];

const validPriorities = [
  'low',
  'medium',
  'high',
  'critical',
];

if (!validCategories.includes(category)) {
  throw new Error('CategorÃ­a de ticket invÃ¡lida');
}

if (!validPriorities.includes(priority)) {
  throw new Error('Prioridad de ticket invÃ¡lida');
}

// Validar y normalizar el resumen
if (typeof ticket.summary !== 'string' || !ticket.summary.trim()) {
  throw new Error('El resumen de Ollama estÃ¡ vacÃ­o o no es texto');
}

const summary = ticket.summary.trim();

// Validar acciones sugeridas
if (!Array.isArray(ticket.suggestedActions)) {
  throw new Error('Las acciones sugeridas deben ser un array');
}


if (ticket.suggestedActions.length > 10) {
  throw new Error('No se permiten mÃ¡s de 10 acciones sugeridas');
}

const suggestedActions = ticket.suggestedActions.map((action) => {
  if (typeof action !== 'string' || !action.trim()) {
    throw new Error('Cada acciÃ³n sugerida debe ser un texto no vacÃ­o');
  }

  const normalizedAction = action.trim();

  if (normalizedAction.length > 500) {
    throw new Error('Una acciÃ³n sugerida supera los 500 caracteres');
  }

  return normalizedAction;
});


if (typeof ticket.requiresHumanReview !== 'boolean') {
  throw new Error('requiresHumanReview debe ser boolean');
}

// Preparar datos para PostgreSQL
return [
  {
    json: {
      idempotencyKey: $('Validar entrada').first().json.idempotencyKey,
      title: (original.title ?? description).trim().slice(0, 200),
      description: description.trim(),
      requester: original.requester ?? null,
      category,
      priority,
      summary,
      suggestedActions,
      requiresHumanReview: ticket.requiresHumanReview,
      status: 'open',
    },
  },
];
